<script setup lang="ts">import{onMounted,ref}from'vue';import{statsApi}from'../api/stats';import PageHeader from'../components/PageHeader.vue';const count=ref<any>({}),size=ref<any>({}),depth=ref<any>({}),top=ref<any[]>([]),empty=ref<any[]>([]),levels=ref<any[]>([]);async function load(){const all=await Promise.allSettled([statsApi.count(),statsApi.size(),statsApi.depth(),statsApi.top(),statsApi.empty(),statsApi.levels()]);const val=(i:number)=>all[i].status==='fulfilled'?(all[i] as any).value.data:{};count.value=val(0)||{};size.value=val(1)||{};depth.value=val(2)||{};top.value=Array.isArray(val(3))?val(3):val(3)?.items||[];empty.value=Array.isArray(val(4))?val(4):val(4)?.items||[];levels.value=Array.isArray(val(5))?val(5):val(5)?.levels||[]};onMounted(load);const pick=(o:any,...keys:string[])=>{for(const k of keys)if(o?.[k]!==undefined)return o[k];return '—'}</script>
<template><PageHeader title="统计分析" description="从规模、容量与层级结构了解目录概况"><button class="btn secondary" @click="load">↻ 刷新数据</button></PageHeader><div class="grid grid-4"><div class="card stat-card"><small>文件总数</small><strong>{{pick(count,'fileCount','files','file_count')}}</strong><span>当前目录树</span></div><div class="card stat-card"><small>文件夹总数</small><strong>{{pick(count,'dirCount','directories','dir_count')}}</strong><span>包含所有层级</span></div><div class="card stat-card"><small>占用空间</small><strong>{{pick(size,'formatted','totalSize','size')}}</strong><span>目录汇总大小</span></div><div class="card stat-card"><small>最大深度</small><strong>{{pick(depth,'maxDepth','depth')}}</strong><span>树形层级</span></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h3 class="card-title">最大文件</h3><div v-for="(r,i) in top" :key="i" class="list-row"><span>{{r.name||r.path||r}}</span><b>{{r.size??''}}</b></div><div v-if="!top.length" class="empty">暂无数据</div></div><div class="card"><h3 class="card-title">空目录</h3><div v-for="(r,i) in empty" :key="i" class="list-row">{{r.path||r.name||r}}</div><div v-if="!empty.length" class="empty">暂无空目录</div></div><div class="card"><h3 class="card-title">每层节点分布</h3><div v-for="(r,i) in levels" :key="i" class="list-row">第 {{r.level??i}} 层 <b>{{r.count??r.nodes??r}}</b></div><div v-if="!levels.length" class="empty">暂无层级数据</div></div></div></template>
